    example: { label: 'If input is: abc / 3', output: 'def', explanation: 'a becomes d, b becomes e, c becomes f. Each letter shifted 3 positions forward.' },
    starterCode: 'declare var process: any;\nlet input = \'\';\nprocess.stdin.resume();\nprocess.stdin.setEncoding(\'utf8\');\nprocess.stdin.on(\'data\', (d: string) => input += d);\nprocess.stdin.on(\'end\', () => {\n  const lines = input.trim().split(\'\\n\');\n\n  // Encrypt and print\n});\n',
